 41 | fn validate<'a>(
 42 |     manifest: &'a Manifest,
 43 |     version: &str,
 44 |     target: &str,
 45 | ) -> Result<&'a Distribution, String> {
 46 |     semver::Version::parse(version).map_err(|_| "invalid CLI release version")?;
 47 |     if manifest.schema_version != 1
 48 |         || manifest.name != "ice-cli"
 49 |         || manifest.version != version
 50 |         || canonical_repository(&manifest.repository)? != REPOSITORY
 51 |         || manifest.tag != format!("v{version}")
 52 |     {
 53 |         return Err(
 54 |             "CLI manifest schema, package, version, repository or tag does not match".into(),
 55 |         );
 56 |     }
 57 |     if manifest.source_commit.len() != 40
 58 |         || !manifest
 59 |             .source_commit
 60 |             .bytes()
 61 |             .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
 62 |     {
 63 |         return Err("CLI manifest must identify its full source commit".into());
 64 |     }
 65 |     let distribution = manifest.targets.get(target).ok_or_else(|| {
 66 |         format!("no prebuilt CLI for exact target {target}; select --build explicitly")
 67 |     })?;
 68 |     if distribution.size == 0
 69 |         || distribution.size > MAX_ARCHIVE
 70 |         || !matches!(distribution.format.as_str(), "zip" | "tar.gz")
 71 |     {
 72 |         return Err("invalid CLI archive format or size".into());
 73 |     }
 74 |     if distribution.binary.path
 75 |         != if target.contains("windows") {
 76 |             "icers.exe"
 77 |         } else {
 78 |             "icers"
 79 |         }
 80 |     {
 81 |         return Err("CLI manifest must declare the flat icers executable filename".into());
 82 |     }
 83 |     for sha in [&distribution.sha256, &distribution.binary.sha256] {
 84 |         if sha.len() != 64
 85 |             || !sha
 86 |                 .bytes()
 87 |                 .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
 88 |         {
 89 |             return Err("invalid CLI manifest SHA-256".into());
 90 |         }
 91 |     }
 92 |     validate_release_asset_url(&distribution.url, REPOSITORY, &manifest.tag)?;
 93 |     Ok(distribution)
