158 | pub(crate) fn canonical_repository(value: &str) -> Result<String, String> {
159 |     let value = value.trim().strip_prefix("git+").unwrap_or(value.trim());
160 |     let value = if value.contains("://") {
161 |         value.to_string()
162 |     } else {
163 |         format!("https://github.com/{value}")
164 |     };
165 |     let url = reqwest::Url::parse(&value).map_err(|_| "invalid GitHub repository".to_string())?;
166 |     if url.scheme() != "https"
167 |         || url.host_str() != Some("github.com")
168 |         || !url.username().is_empty()
169 |         || url.password().is_some()
170 |         || url.port().is_some()
171 |     {
172 |         return Err("prebuilt repository must be an HTTPS GitHub repository; use --build for other repositories".into());
173 |     }
174 |     let segments: Vec<_> = url
175 |         .path_segments()
176 |         .ok_or("invalid GitHub repository path")?
177 |         .collect();
178 |     if segments.len() < 2 || !valid_segment(segments[0]) {
179 |         return Err("repository must identify a GitHub owner and repository".into());
180 |     }
181 |     let repo = segments[1].strip_suffix(".git").unwrap_or(segments[1]);
182 |     if !valid_segment(repo) {
183 |         return Err("invalid GitHub repository name".into());
184 |     }
185 |     if segments.len() > 2
186 |         && !segments[2..].iter().all(|s| s.is_empty())
187 |         && !matches!(segments[2], "tree" | "blob")
188 |     {
189 |         return Err("unsupported GitHub repository URL path".into());
190 |     }
191 |     Ok(format!(
192 |         "https://github.com/{}/{}",
193 |         segments[0].to_ascii_lowercase(),
194 |         repo.to_ascii_lowercase()
195 |     ))

44 | }
