189 | /// The core migration (no env gate): if `agent/` is absent but flat files exist
190 | /// under `root`, move `{auth.json,models.json,.setup_done}` into
191 | /// `agent/`. Idempotent. Factored out so tests can drive it against a temp
192 | /// root/agent pair without touching the env (the public
193 | /// [`migrate_legacy_layout`] short-circuits on an env override, which tests
194 | /// can't unset portably while other tests run).
195 | fn migrate_legacy_layout_in(root: &Path, agent: &Path) -> Result<usize, ConfigError> {
196 |     // If the agent dir already exists with any content, assume already migrated.
197 |     if agent.exists() {
198 |         return Ok(0);
199 |     }
200 |     // Probe for a flat file. If none, nothing to migrate.
201 |     let flat_auth = root.join("auth.json");
202 |     let flat_models = root.join("models.json");
203 |     if !flat_auth.exists() && !flat_models.exists() {
204 |         return Ok(0);
205 |     }
206 |     std::fs::create_dir_all(agent).map_err(|e| ConfigError::Write {
207 |         path: agent.to_path_buf(),
208 |         source: e,
209 |     })?;
210 |     let mut moved = 0usize;
211 |     for leaf in ["auth.json", "models.json", ".setup_done"] {
212 |         let from = root.join(leaf);
213 |         let to = agent.join(leaf);
214 |         if from.exists() && !to.exists() {
215 |             // `rename` across the same filesystem is atomic; fall back to copy
216 |             // + remove on cross-device (rare for a home dir).
217 |             if let Err(_e) = std::fs::rename(&from, &to) {
218 |                 if std::fs::copy(&from, &to).is_ok() {
219 |                     let _ = std::fs::remove_file(&from);
220 |                 }
221 |             }
222 |             moved += 1;
223 |         }
224 |     }
225 |     Ok(moved)

